import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-11-13","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-11-13","date":"2024-11-13T00:00:00.000Z","updated":"2024-11-13T00:00:00.000Z","tags":["Ceph","RGW","Distributed Storage","Object Storage","Integration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-13.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-13.md","lastUpdated":1780459816000}'),a={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-11-13.md"};function s(i,e,p,_,g,l){return r(),n("div",null,[...e[0]||(e[0]=[o("<p>本次会议主要讨论了Ceph RGW的多个重要议题，包括RGW与Vector DB的集成、版本化桶的动态resharding、parallel resharding的进展、Keystone缓存优化以及bucket通知的Zone过滤和负过滤功能。</p><ol><li><p><strong>RGW与Vector DB集成方案讨论</strong> 讨论了如何将RGW中的数据集成为Vector DB的一部分，以支持RAG或数据科学研究。提出了使用Knative作为服务框架，并通过RGW的bucket通知机制触发Knative函数的解决方案。技术细节包括使用Rook部署RGW以支持bucket通知，以及将embedding模型部署在Kubernetes集群内。</p></li><li><p><strong>Ceph RGW版本化桶的动态resharding问题</strong> 讨论了版本化桶在动态resharding时遇到的问题，并提出了使用archive zone减少max_objects_per_shard以避免omap警告的解决方案。</p></li><li><p><strong>Parallel Resharding项目更新</strong> 更新了parallel resharding项目的进展，指出已提交draft PR并测试通过，但依赖其他PR的合并和清理。讨论了RGW并发IO阻塞在条件变量上的问题，以及为bucket元数据读写提供异步接口的必要性。</p></li><li><p><strong>Keystone缓存问题讨论</strong> 讨论了Keystone缓存miss导致频繁访问Keystone的问题，并提出了使用mutex锁避免多次访问Keystone的解决方案。</p></li><li><p><strong>其他议题</strong> Alex计划开始处理bucket通知的Zone过滤和负过滤功能，Marcus分享了一个用于测试Swift操作的独立程序。</p></li></ol><p>会议总结： 本次会议重点讨论了RGW的多项重要特性和工作进展，各项目负责人将继续推进相关工作，并计划在后续会议中进行进一步讨论和演示。</p>",3)])])}const R=t(a,[["render",s]]);export{d as __pageData,R as default};
